COMMENT ON COLUMN "appointment_slot"."is_overbook" IS '[Optional] Overbooked slot. If the source does not send it: Blank';
COMMENT ON COLUMN "appointment_slot"."version" IS '[Mandatory] 1 for the first row; higher for each change. If the source does not send it: Always set by us';
