COMMENT ON COLUMN "claim"."denied_amount" IS '[Important] Rollup: denied. If the source does not send it: Rebuild from payments';
COMMENT ON COLUMN "claim"."balance" IS '[Important] Rollup: still open. If the source does not send it: Rebuild from payments';
COMMENT ON COLUMN "claim"."last_payment_date" IS '[Important] Rollup: latest payment. If the source does not send it: Rebuild from payments';
COMMENT ON COLUMN "claim"."last_status_date" IS '[Important] Rollup: latest status event. If the source does not send it: Rebuild from events';
